/**
 * Typed view over the committed competitor-benchmark results: basin vs other
 * optimization crates on matched (solver, problem) cases, recorded as
 * suboptimality-vs-time convergence traces.
 *
 * The JSON is generated by `web/scripts/collect-competitors.ts` (run via
 * `npm run collect:competitors`) from the `trace` harness output, never
 * hand-edited. This module just types it and adds display metadata, reusing
 * the solver and problem vocabulary from `./benchmarks`.
 */

import {
    PROBLEM_LABELS as BASE_PROBLEM_LABELS,
    SOLVER_LABELS as BASE_SOLVER_LABELS,
    type Solver as BaseSolver,
} from "./benchmarks";
import rawData from "./competitor-benchmarks.json";

export type Solver = BaseSolver | "lbfgsb";
export const SOLVER_LABELS: Record<Solver, string> = {
    ...BASE_SOLVER_LABELS,
    lbfgsb: "L-BFGS-B",
};
export const PROBLEM_LABELS: Record<string, string> = {
    ...BASE_PROBLEM_LABELS,
    quadratic_30d: "Constrained quadratic",
    constrained_quadratic: "Ball-constrained quadratic",
    extended_rosenbrock: "Bounded extended Rosenbrock",
    rotated_ellipsoid: "Rotated ellipsoid",
    ackley: "Ackley",
};

/** Competing libraries a case is run against. */
export type Library =
    | "basin"
    | "argmin"
    | "gomez"
    | "nlopt"
    | "slsqp"
    | "lbfgsb"
    | "cmaes"
    | "levenberg-marquardt"
    | "cobyla";

export interface RunSummary {
    point: (number | null)[];
    cost: number | null;
    violation: number | null;
    objectiveCalls: number;
    residualCalls: number;
    jacobianCalls: number;
    gradientCalls: number;
    constraintCalls: number;
    status: string;
    verified: boolean;
    iterations?: number;
    projectedGradient?: number | null;
}

/** One `(time, suboptimality)` sample on a convergence trace. */
export interface TracePoint {
    /** Wall-clock time, nanoseconds, including initialization (median over repetitions). */
    tNs: number;
    /** Suboptimality `f(x) − f*`, floored at a small positive value. */
    subopt: number;
}

export interface CompetitorResult {
    solver: Solver;
    problem: string;
    n: number;
    library: Library;
    /** Each stochastic seed retains its own trace and diagnostics. */
    seed?: number;
    points: TracePoint[];
    violations?: { tNs: number; violation: number }[];
    summary?: RunSummary;
}

export interface CompetitorBenchmarks {
    /** ISO date (YYYY-MM-DD) the results were measured. */
    generatedAt: string;
    env: {
        os: string;
        arch: string;
        cpu: string;
        compiler: string;
        revision: string;
        dirty: boolean;
        threads: number;
    };
    repetitions: number;
    versions: Record<string, string>;
    /** Safety cap for GD, Nelder–Mead, and L-BFGS; other caps are documented per case. */
    iterations: number;
    results: CompetitorResult[];
}

export const COMPETITOR_BENCHMARKS = rawData as CompetitorBenchmarks;

export const LIBRARY_ORDER: Library[] = [
    "basin",
    "argmin",
    "gomez",
    "slsqp",
    "nlopt",
    "levenberg-marquardt",
    "cobyla",
    "lbfgsb",
    "cmaes",
];

export const LIBRARY_LABELS: Record<Library, string> = {
    basin: "basin",
    argmin: "argmin",
    gomez: "gomez",
    slsqp: "slsqp",
    nlopt: "nlopt",
    "levenberg-marquardt": "LM crate",
    cobyla: "cobyla",
    lbfgsb: "lbfgsb (C)",
    cmaes: "cmaes",
};

