/** Libraries a case actually has data for, in canonical order. */
export function librariesFor(solver: Solver, problem: string): Library[] {
    return LIBRARY_ORDER.filter((lib) =>
        COMPETITOR_BENCHMARKS.results.some(
            (r) =>
                r.solver === solver &&
                r.problem === problem &&
                r.library === lib,
        ),
    );
}

/** Reject incomplete or malformed measurements before replacing published data. */
export function validateCompetitorResults(raw: unknown): CompetitorResult[] {
    if (!Array.isArray(raw))
        throw new Error("Expected an array of competitor results");
    const rows = raw as CompetitorResult[];
    const keys = new Set<string>();
    for (const row of rows) {
        const c = COMPETITOR_CASES.find(
            (c) => c.solver === row?.solver && c.problem === row?.problem,
        );
        const key = resultKey(row);
        if (!c?.libraries.includes(row.library) || keys.has(key))
            throw new Error(`Unexpected or duplicate result: ${key}`);
        if (
            c.seeds
                ? !Number.isInteger(row.seed) ||
                  !c.seeds.includes(row.seed as number)
                : row.seed !== undefined
        )
            throw new Error(`Unexpected seed: ${key}`);
        keys.add(key);
        if (!Number.isInteger(row.n) || row.n !== c.n)
            throw new Error(`Invalid dimension: ${key}`);
        validatePoints(row.points, "subopt", key);
        if (row.violations !== undefined)
            validatePoints(row.violations, "violation", key);
        if (["lm", "cobyla", "slsqp", "lbfgsb", "cmaes"].includes(c.solver)) {
            const s = row.summary;
            if (
                !s ||
                typeof s.status !== "string" ||
                typeof s.verified !== "boolean"
            )
                throw new Error(`Missing run diagnostics: ${key}`);
            for (const count of [
                s.objectiveCalls,
                s.residualCalls,
                s.jacobianCalls,
                s.gradientCalls,
                s.constraintCalls,
            ]) {
                if (!Number.isInteger(count) || count < 0)
                    throw new Error(`Invalid callback count: ${key}`);
            }
            if (
                !Array.isArray(s.point) ||
                s.point.length !== row.n ||
                [...s.point, s.cost, s.violation].some(
                    (v) => v !== null && !Number.isFinite(v),
                )
            )
                throw new Error(`Invalid returned solution: ${key}`);
            if (s.violation !== null && s.violation < 0)
                throw new Error(`Negative violation: ${key}`);
            if (
                s.verified &&
                ([...s.point, s.cost, s.violation].includes(null) ||
                    row.points.length === 0)
            )
                throw new Error(`Invalid verified solution: ${key}`);
            if (
                s.verified &&
                c.solver === "lm" &&
                (s.residualCalls < 1 || s.jacobianCalls < 1)
            )
                throw new Error(`Missing derivative counts: ${key}`);
            if (
                s.verified &&
                (c.solver === "cobyla" || c.solver === "slsqp") &&
                (s.objectiveCalls < 1 || !row.violations?.length)
            )
                throw new Error(`Missing constrained measurements: ${key}`);
            if (c.solver === "lbfgsb") {
                if (
                    !Number.isInteger(s.iterations) ||
                    (s.iterations ?? -1) < 0 ||
                    s.projectedGradient === undefined ||
                    (s.projectedGradient !== null &&
                        (!Number.isFinite(s.projectedGradient) ||
                            s.projectedGradient < 0))
                )
                    throw new Error(`Invalid L-BFGS-B diagnostics: ${key}`);
                if (
                    s.verified &&
                    (s.projectedGradient === null ||
                        s.projectedGradient > 1e-8 * (1 + 1e-6) ||
                        s.objectiveCalls < 1 ||
                        s.objectiveCalls !== s.gradientCalls)
                )
                    throw new Error(
                        `Invalid verified L-BFGS-B solution: ${key}`,
                    );
            }
            if (c.solver === "cmaes") {
                if (
                    !Number.isInteger(s.iterations) ||
                    (s.iterations ?? -1) < 0 ||
                    (s.iterations ?? Infinity) > 10_000 ||
                    s.objectiveCalls > 100_000 + 16 ||
                    s.residualCalls !== 0 ||
                    s.jacobianCalls !== 0 ||
                    s.gradientCalls !== 0 ||
                    s.constraintCalls !== 0
                )
                    throw new Error(`Invalid CMA-ES diagnostics: ${key}`);
                if (
                    s.verified &&
                    (s.cost === null ||
                        s.cost < 0 ||
                        s.cost > 1e-8 ||
                        (s.iterations ?? 0) < 1 ||
                        s.objectiveCalls !==
                            (s.iterations ?? 0) *
                                (row.library === "basin" ? 17 : 16))
                )
                    throw new Error(`Invalid verified CMA-ES solution: ${key}`);
            }
        }
    }
    for (const c of COMPETITOR_CASES) {
        for (const library of c.libraries) {
            for (const seed of c.seeds ?? [undefined]) {
                const key = resultKey({ ...c, library, seed });
                if (!keys.has(key)) throw new Error(`Missing result: ${key}`);
            }
        }
    }
    return rows;
}

function resultKey(
    row: Pick<CompetitorResult, "solver" | "problem" | "library" | "seed">,
) {
    return `${row?.solver}/${row?.problem}/${row?.library}${row?.seed === undefined ? "" : `/seed${row.seed}`}`;
}

function validatePoints(
    points: unknown,
    valueKey: "subopt" | "violation",
    key: string,
) {
    if (!Array.isArray(points)) throw new Error(`Missing trace: ${key}`);
    let previous = -1;
    for (const point of points) {
        if (
            !point ||
            !Number.isFinite(point.tNs) ||
            point.tNs < previous ||
            point.tNs < 0 ||
            !Number.isFinite(point[valueKey]) ||
            (valueKey === "subopt" ? point[valueKey] <= 0 : point[valueKey] < 0)
        )
            throw new Error(`Invalid trace point: ${key}`);
        previous = point.tNs;
    }
}
